<?php $page_title='Medical Record';require_once __DIR__.'/../includes/header.php';$p=$pdo->query("SELECT id,name FROM patients ORDER BY name")->fetchAll();$d=$pdo->query("SELECT id,name FROM doctors ORDER BY name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO medical_records(patient_id,doctor_id,visit_date,diagnosis,notes,vitals) VALUES(?,?,?,?,?,?)")->execute([$_POST['patient_id'],$_POST['doctor_id'],$_POST['visit_date'],$_POST['diagnosis'],$_POST['notes'],$_POST['vitals']]);header('Location:index.php');exit;}?><h2>Add Medical Record</h2><div class="card p-4 mt-3"><form method="post"><div class="row g-3"><div class="col-md-6"><label>Patient</label><select name="patient_id" class="form-select"><?php foreach($p as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Doctor</label><select name="doctor_id" class="form-select"><?php foreach($d as $x):?><option value="<?=$x['id']?>">Dr. <?=e($x['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label>Visit Date</label><input type="date" name="visit_date" value="<?=date('Y-m-d')?>" class="form-control"></div><div class="col-md-8"><label>Vitals</label><input name="vitals" class="form-control" placeholder="BP, pulse, temperature..."></div><div class="col-12"><label>Diagnosis</label><input name="diagnosis" class="form-control" required></div><div class="col-12"><label>Clinical Notes</label><textarea name="notes" rows="5" class="form-control"></textarea></div></div><button class="btn btn-primary mt-3">Save Record</button></form></div><?php require_once __DIR__.'/../includes/footer.php';?>